1: import assert from "node:assert/strict";
2: import test from "node:test";
3: import fs from "node:fs";
4: import os from "node:os";
5: import path from "node:path";
6: import { fileURLToPath } from "node:url";
7: import { spawnSync } from "node:child_process";
8: import ts from "typescript";
9: import { annotate, jsonType } from "./annotate.mjs";
10: import { compareEmission, sha256 } from "./emission.mjs";
11: 
12: const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
13: const raw = `export class Example {
14:  value: string;
15:  constructor(source: any = {}) {
16:   if ('string' === typeof source) source = JSON.parse(source);
17:   this.value = source["value"];
18:  }
19: }`;
20: const refine = () => annotate(raw).text;
21: 
22: test("annotation is deterministic and contains no explicit-any", () => {
23:   const first = refine();
24:   assert.equal(first, refine());
25:   assert.match(first, /constructor\(source: unknown = \{\}\)/);
26:   assert.match(first, /value: string;/);
27:   const source = ts.createSourceFile("models.ts", first, ts.ScriptTarget.Latest, true);
28:   function visit(node) {
29:     assert.notEqual(node.kind, ts.SyntaxKind.AnyKeyword);
30:     ts.forEachChild(node, visit);
31:   }
32:   visit(source);
33: });
34: test("unknown public types require their owning Go metadata", () => {
35:   for (const type of ["any", "Array<any>", "{ [key: string]: any }"])
36:     assert.throws(() => annotate(raw.replace("value: string;", `value: ${type};`)), /Go-owned ts_type/);
37: });
38: test("JSONValue metadata is retained, not inferred by the adapter", () => {
39:   const tagged = raw.replace("value: string;", "value: JSONValue;");
40:   assert.match(annotate(tagged).text, /value: JSONValue;/);
41:   assert.equal(annotate(tagged).text.split("export type JSONValue =").length, 2);
42: });
43: test("alias collision is refused", () => {
44:   assert.throws(() => annotate(raw.replace("class Example", "class JSONValue")), /name collision/);
45:   assert.throws(() => annotate("type JSONValue = string;\n" + raw), /only named classes/);
46: });
47: test("empty and syntactically invalid upstream output are refused", () => {
48:   assert.throws(() => annotate(""), /empty module/);
49:   assert.throws(() => annotate("export class {"), /parse failure/);
50: });
51: test("new runtime declarations and constructor statements are refused", () => {
52:   assert.throws(() => annotate("console.log('changed');\n" + raw), /only named classes/);
53:   assert.throws(() => annotate(raw.replace('this.value =', 'console.log(source); this.value =')), /field count/);
54:   assert.throws(() => annotate(raw.replace('this.value = source["value"]', 'this.value = String(source)')), /nested conversion/);
55: });
56: test("missing or duplicate constructor writes are refused", () => {
57:   assert.throws(() => annotate(raw.replace('this.value = source["value"];', "")), /field count/);
58:   assert.throws(() => annotate(raw.replace('this.value = source["value"];', 'this.other = source["value"];')), /unknown or repeated/);
59: });
60: test("upstream helper-template drift is refused", () => {
61:   assert.throws(() => annotate(raw.replace(/}\s*$/, "convertValues(a: any): any { return a; }\n}")), /convertValues template/);
62: });
63: test("new transform operators are refused rather than guessed", () => {
64:   assert.throws(() => annotate(raw.replace('source["value"];', 'source["value"] || new Date(source["value"]);')), /guard operator/);
65: });
66: test("computed public field names are refused", () => {
67:   assert.throws(() => annotate(raw.replace("value: string;", '["value"]: string;')), /public field/);
68: });
69: test("compiler guard proves the unchanged emitted JavaScript", () => {
70:   const result = compareEmission(raw, refine(), root);
71:   assert.equal(result.identical, true);
72:   assert.ok(result.javascript_bytes > 0);
73:   assert.equal(result.overrides.noEmit, false);
74:   assert.equal(result.overrides.allowImportingTsExtensions, false);
75: });
76: test("compiler guard rejects a runtime change that still compiles", () => {
77:   const broken = refine().replace('(source as Record<string, unknown>)["value"] as Example["value"]', '"constant"');
78:   assert.notEqual(broken, refine());
79:   assert.throws(() => compareEmission(raw, broken, root), /JavaScript changed/);
80: });
81: test("compiler guard rejects type errors rather than emitting partial output", () => {
82:   assert.throws(() => compareEmission(raw, refine().replace("value: string;", "value: MissingType;"), root), /emission failed/);
83: });
84: test("compiler guard refuses runtime imports", () => {
85:   assert.throws(() => compareEmission(raw, 'import "missing-module";\n' + refine(), root), /import-free/);
86: });
87: test("Go-owned JSON union changes no runtime emission", () => {
88:   const tagged = raw.replace("value: string;", "value: JSONValue;");
89:   assert.equal(compareEmission(tagged, annotate(tagged).text, root).javascript_sha256,
90:     compareEmission(raw, refine(), root).javascript_sha256);
91:   assert.match(jsonType, /null/);
92: });
