94: test("real generation CLI is reproducible, detects stale output and preserves failures", { timeout: 240000 }, async t => {
95:   const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "ollama-codegen-check-"));
96:   const target = path.join(scratch, "generated.ts");
97:   const committed = path.join(root, "codegen/gotypes.gen.ts");
98:   const original = fs.readFileSync(committed);
99:   const cli = (args, env = process.env) => {
100:     const argv = [path.join(root, "codegen/generate.mjs"), "--output", target, ...args];
101:     const result = spawnSync(process.execPath, argv, { cwd: root, env, encoding: "utf8", timeout: 180000, maxBuffer: 8 * 1024 * 1024 });
102:     console.log(JSON.stringify({ argv, exit_code: result.status, error: result.error?.message,
103:       stdout: result.stdout, stderr: result.stderr }));
104:     assert.equal(result.error, undefined);
105:     return result;
106:   };
107:   try {
108:     let first;
109:     await t.test("fresh Go generation twice produces identical bytes", () => {
110:       assert.equal(cli([]).status, 0);
111:       first = fs.readFileSync(target);
112:       assert.equal(cli([]).status, 0);
113:       assert.deepEqual(fs.readFileSync(target), first);
114:     });
115:     await t.test("check verifies the final transformed bytes without writing", () => {
116:       assert.equal(cli(["--check"]).status, 0);
117:       assert.deepEqual(fs.readFileSync(target), first);
118:     });
119:     await t.test("check rejects stale bytes without replacing them", () => {
120:       fs.appendFileSync(target, "\n// deliberate stale-file probe\n");
121:       const stale = fs.readFileSync(target);
122:       const result = cli(["--check"]);
123:       assert.equal(result.status, 1);
124:       assert.match(result.stderr, /types are stale/);
125:       assert.deepEqual(fs.readFileSync(target), stale);
126:     });
127:     await t.test("unavailable Go returns nonzero and preserves the existing target", () => {
128:       const stale = fs.readFileSync(target);
129:       const result = cli([], { ...process.env, PATH: scratch });
130:       assert.equal(result.status, 1);
131:       assert.match(result.stderr, /Go generation failed/);
132:       assert.deepEqual(fs.readFileSync(target), stale);
133:     });
134:     await t.test("malformed command options fail before touching output", () => {
135:       const before = fs.readFileSync(target);
136:       const result = cli(["--unsupported"]);
137:       assert.equal(result.status, 1);
138:       assert.match(result.stderr, /Usage:/);
139:       assert.deepEqual(fs.readFileSync(target), before);
140:     });
141:     await t.test("the alternative target never changes the committed output", () => {
142:       assert.equal(sha256(fs.readFileSync(committed)), sha256(original));
143:     });
144:   } finally {
145:     fs.rmSync(scratch, { recursive: true, force: true });
146:   }
147: });
